package app

import "slices"

// All state changes are called under the indent row lock. Actor/time stamps are
// generated by the server; planning input cannot replace an audit or a milestone.
func sampleAdvance(u *User, status, action string, d, p M, now string) (string, error) {
	producer := sampleProduction(u)
	qa := sampleRead(u) && u.Role == "Quality" && u.Can("quality")

	if action == "file_review" {
		if !producer {
			return "", forbidden()
		}
		if slices.Contains([]string{"Handed over", "Rejected"}, status) {
			return "", bad("This indent is closed.")
		}
		result, note := str(d, "result"), str(d, "note")
		if !slices.Contains([]string{"Clear", "Missing"}, result) || len(note) > 2000 || result == "Missing" && note == "" {
			return "", bad("Choose file clear or missing, and describe missing items.")
		}
		p["file_clearance"] = result
		p["file_review_note"] = note
		p["file_review_by"] = u.Name
		p["file_review_at"] = now
		return status, nil
	}
	if action == "buyer_feedback" {
		if !sampleRead(u) || u.Role != "Marketing" {
			return "", forbidden()
		}
		if status != "Handed over" {
			return "", bad("Record customer feedback after final handover.")
		}
		result, note := str(d, "result"), str(d, "note")
		if !slices.Contains([]string{"Pass", "Fail", "Comments"}, result) || len(note) > 2000 || note == "" {
			return "", bad("Choose pass, fail or comments and enter the buyer feedback.")
		}
		p["buyer_result"] = result
		p["buyer_comments"] = note
		p["buyer_feedback_by"] = u.Name
		p["buyer_feedback_at"] = now
		return status, nil
	}
	if action == "plan" {
		if !producer || slices.Contains([]string{"Handed over", "Rejected"}, status) {
			return "", forbidden()
		}
		v, e := sampleStrings(d["production"], sampleProductionFields)
		if e != nil {
			return "", e
		}
		for k, value := range v {
			p[k] = value
		}
		return status, nil
	}
	if action == "pattern" {
		if !(producer || sampleRead(u) && u.Role == "Development" && u.Can("develop")) {
			return "", forbidden()
		}
		if status != "Ready" {
			return "", bad("Only ready indents can finish patterns.")
		}
		p["pattern_actual"] = now
		p["pattern_completed_by"] = u.Name
		return "Pattern ready", nil
	}
	if action == "audit_start" || action == "audit" {
		if !qa {
			return "", forbidden()
		}
		if !slices.Contains([]string{"Awaiting audit", "Audit"}, status) {
			return "", bad("Complete finishing before starting the audit.")
		}
		if action == "audit_start" {
			if status == "Audit" {
				return "", bad("Audit already started.")
			}
			p["audit_started"] = now
			return "Audit", nil
		}
		next := str(d, "result")
		if !slices.Contains([]string{"Approved", "Rework", "Rejected"}, next) {
			return "", bad("Choose an audit result.")
		}
		note := str(d, "note")
		if len(note) > 2000 || (next != "Approved" && note == "") {
			return "", bad("Enter audit remarks.")
		}
		report, e := sampleAudit(d["audit"])
		if e != nil {
			return "", e
		}
		report["result"] = next
		report["remarks"] = note
		report["auditor"] = u.Name
		report["auditor_id"] = u.ID
		report["signed_at"] = now
		reports, _ := p["audit_reports"].([]any)
		if len(reports) >= 50 {
			return "", bad("This indent has reached 50 audit reports. Create a linked remake request.")
		}
		report["revision"] = len(reports) + 1
		p["audit_reports"] = append(reports, report)
		p["audit_remarks"] = note
		p["audited_by"] = u.Name
		p["audit_actual"] = now
		p["audit_result"] = next
		return next, nil
	}
	if action == "handover" || action == "merchant_handover" {
		if !(producer || sampleRead(u) && u.Role == "Marketing") {
			return "", forbidden()
		}
		if action == "merchant_handover" {
			if status != "Approved" {
				return "", bad("QA approval is required before merchant or showroom handover.")
			}
			if str(p, "handover_dc") == "" {
				return "", bad("Save the handover DC first.")
			}
			target := str(d, "destination")
			if !slices.Contains([]string{"Merchant", "Showroom"}, target) {
				return "", bad("Choose merchant or showroom.")
			}
			p["merchant_actual"] = now
			p["merchant_handover_by"] = u.Name
			p["handover_destination"] = target
			if target == "Showroom" {
				return "Showroom", nil
			}
			return "With merchant", nil
		}
		if !slices.Contains([]string{"With merchant", "Showroom"}, status) {
			return "", bad("Record merchant or showroom handover first.")
		}
		v, e := sampleStrings(d["dispatch"], []string{"awb", "dispatch_to", "dispatch_from", "dispatch_contact"})
		if e != nil {
			return "", e
		}
		for _, k := range []string{"awb", "dispatch_to", "dispatch_from"} {
			if str(v, k) == "" {
				return "", bad("Enter shipment / AWB reference and the recipient and sender addresses.")
			}
		}
		for k, value := range v {
			p[k] = value
		}
		p["handover_actual"] = now
		p["handover_by"] = u.Name
		return "Handed over", nil
	}
	if !producer {
		return "", forbidden()
	}
	var next, stamp string
	switch action {
	case "cut":
		if str(p, "file_clearance") != "Clear" {
			return "", bad("Review and accept the sample file before cutting.")
		}
		if status != "Pattern ready" {
			return "", bad("Complete the pattern first.")
		}
		for _, k := range []string{"fabric_update_date", "trims_update_date", "style_update_date"} {
			if str(p, k) == "" {
				return "", bad("Record fabric, trims and style readiness before cutting.")
			}
		}
		next, stamp = "Cut", "cut_actual"
	case "allocate":
		if status != "Cut" {
			return "", bad("Complete cutting before allocating a tailor.")
		}
		if str(p, "sample_maker") == "" {
			return "", bad("Save the sample tailor / maker before allocating.")
		}
		next, stamp = "Allocated", "allocation_actual"
	case "sew_start":
		if !slices.Contains([]string{"Allocated", "Rework"}, status) {
			return "", bad("Allocate the sample or receive a QA rework request first.")
		}
		for _, key := range []string{"sewing_actual", "finishing_started", "finishing_actual", "audit_started", "audit_actual", "audit_result"} {
			delete(p, key)
		}
		next, stamp = "Sewing", "sewing_started"
	case "sew":
		if status != "Sewing" {
			return "", bad("Start sewing before marking it complete.")
		}
		next, stamp = "Sewn", "sewing_actual"
	case "finish_start":
		if status != "Sewn" {
			return "", bad("Complete sewing before finishing.")
		}
		next, stamp = "Finishing", "finishing_started"
	case "finish":
		if status != "Finishing" {
			return "", bad("Start finishing before sending to QA.")
		}
		next, stamp = "Awaiting audit", "finishing_actual"
	default:
		return "", bad("Choose a valid production action.")
	}
	p[stamp] = now
	p[stamp+"_by"] = u.Name
	return next, nil
}
